interface Analytics {
  views: number;
  clicks: number;
  conversions: number;
}

interface Notification {
  id: number;
  message: string;
  type: 'info' | 'warning' | 'error';
}

interface Settings {
  theme: string;
  emailNotifications: boolean;
  language: string;
}

async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('https://api.example.com/api/analytics').then((r) => r.json()),
      fetch('https://api.example.com/api/notifications').then((r) => r.json()),
      fetch('https://api.example.com/api/settings').then((r) => r.json()),
    ]);

    return { analytics, notifications, settings };
  } catch (error) {
    // Return mock data for build time or error scenarios
    return {
      analytics: { views: 5000, clicks: 1200, conversions: 350 },
      notifications: [
        { id: 1, message: 'Welcome to the dashboard', type: 'info' },
        { id: 2, message: 'System maintenance scheduled', type: 'warning' },
      ],
      settings: {
        theme: 'dark',
        emailNotifications: true,
        language: 'en-US',
      },
    } as {
      analytics: Analytics;
      notifications: Notification[];
      settings: Settings;
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
      <h2>Dashboard Overview</h2>

      <div style={{ marginBottom: '20px' }}>
        <h3>Analytics</h3>
        <p>Views: {analytics.views}</p>
        <p>Clicks: {analytics.clicks}</p>
        <p>Conversions: {analytics.conversions}</p>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <h3>Notifications</h3>
        <ul>
          {notifications.map((note) => (
            <li key={note.id}>
              [{note.type.toUpperCase()}] {note.message}
            </li>
          ))}
        </ul>
      </div>

      <div>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Language: {settings.language}</p>
        <p>Email Notifications: {settings.emailNotifications ? 'On' : 'Off'}</p>
      </div>
    </div>
  );
}

